#!/bin/bash
set -e
echo '[matterlist] install: writing project files'

cat > package.json << 'EOF'
{
  "name": "rdk-matter-device-list",
  "version": "2.0.0",
  "description": "Matter device list: on-demand + startup publish via local broker + bridge",
  "main": "index.js",
  "license": "ISC"
}
EOF

cat > index.js << 'EOF'
const axios = require('axios');
const mqtt = require('mqtt');

const BROKER        = process.env.MATTERLIST_BROKER_URI   || 'tcp://192.168.10.1:1883';
const HUB_API       = process.env.MATTERLIST_HUB_API      || 'http://192.168.1.201:8089/cgi-bin/matterapi.ha';
const REFRESH_TOPIC = process.env.MATTERLIST_REFRESH_TOPIC || 'rdk/matter/devices/refresh';
const LIST_TOPIC    = process.env.MATTERLIST_LIST_TOPIC    || 'rdk/matter/devices/list';

console.log('[matterlist] connecting to local broker ' + BROKER);
const client = mqtt.connect(BROKER, {
  clientId: 'matterlist-' + Math.random().toString(36).slice(2, 10),
  reconnectPeriod: 3000,
  keepalive: 30,
});

// Fetch the hub device list (GET path, no jq dependency) and publish it. Runs
// on startup and whenever a refresh poke arrives, so the cloud gets a fresh
// inventory on demand instead of needing a redeploy.
function refreshDeviceList() {
  const url = HUB_API + '?GET_DEVICES_LIST';
  console.log('[matterlist] fetching device list -> ' + url);
  axios.get(url, { timeout: 15000 })
    .then(function (res) {
      var body = typeof res.data === 'string' ? res.data : JSON.stringify(res.data);
      client.publish(LIST_TOPIC, body, { qos: 1 });
      console.log('[matterlist] published device list to ' + LIST_TOPIC);
    })
    .catch(function (e) {
      console.error('[matterlist] device list fetch failed:', e && e.message);
    });
}

client.on('connect', function () {
  console.log('[matterlist] connected; refresh=' + REFRESH_TOPIC + ' list=' + LIST_TOPIC);
  client.subscribe(REFRESH_TOPIC, { qos: 1 }, function (err) {
    if (err) console.error('[matterlist] subscribe failed:', err.message);
    else console.log('[matterlist] subscribed; waiting for refresh pokes');
  });
  refreshDeviceList();
});
client.on('error', function (e) { console.error('[matterlist] mqtt error:', e && e.message); });
client.on('reconnect', function () { console.log('[matterlist] reconnecting...'); });
client.on('close', function () { console.log('[matterlist] connection closed'); });

client.on('message', function (topic) {
  console.log('[matterlist] refresh poke on ' + topic);
  refreshDeviceList();
});

// Keep the event loop alive for the lifetime of the component.
setInterval(function () {}, 1 << 30);
EOF

echo '[matterlist] install: npm install (Node-10-safe pins)'
npm install mqtt@4.3.7 axios@0.27.2 --cache /tmp/npm-cache --omit=dev
echo '[matterlist] install: done'
